def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start without mutating the input list.
    sorted_intervals = sorted(intervals, key=lambda interval: interval[0])

    merged = []
    for start, end in sorted_intervals:
        if not merged:
            merged.append([start, end])
        else:
            last = merged[-1]
            if start <= last[1]:
                # Overlapping or touching intervals: extend the end.
                last[1] = max(last[1], end)
            else:
                merged.append([start, end])

    return merged
